<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Common\Infrastructure\Driven;

use DateTimeImmutable;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\Gateway\RelyingPartyFilter;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\Gateway\RelyingPartyReadGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\Gateway\TenantTermsOfUseFilter;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\Gateway\TenantTermsOfUseReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserWriteGateway;
use Civi\Lughauth\Features\Access\User\Domain\User;
use Civi\Lughauth\Features\Access\User\Domain\UserApproveOptions;
use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\Gateway\UserAccessTemporalCodeWriteGateway;
use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\UserAccessTemporalCode;
use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\UserAccessTemporalCodeAttributes;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;

/**
 * Infrastructure adapter that centralises all user and tenant lookup logic needed across
 * the various OAuth authentication flows (password, recovery code, registration code, etc.).
 *
 * This class is shared by multiple authentication use cases and acts as a domain service
 * boundary between the OAuth Authentication context and the Access bounded context. It
 * enforces a consistent set of blocking conditions — unknown or disabled tenant, unknown
 * user, wrong tenant, disabled user, blocked user, and unaccepted approval status — throwing
 * a LoginException with an AuthenticationResult::unknowUser payload whenever any condition
 * is violated, which prevents information leakage about the reason for rejection.
 *
 * All rejection paths are logged at error level with structured context (tenant name, user
 * name) so that security incidents can be traced without exposing details to the caller.
 */
class UserLoaderAdapter
{
    use LoggerAwareTrait;

    public function __construct(
        private readonly TenantReadGateway $tenants,
        private readonly UserAccessTemporalCodeWriteGateway $codeWriter,
        private readonly UserReadGateway $users,
        private readonly UserWriteGateway $usersWriter,
        private readonly TenantTermsOfUseReadGateway $terms,
        private readonly RelyingPartyReadGateway $parties
    ) {
    }

    /**
     * Retrieves the UserAccessTemporalCode record for the given user, creating one if it does
     * not yet exist, and returns it ready for further updates within the same transaction.
     */
    public function userCodeForUpdate(User $user): UserAccessTemporalCode
    {
        $code = $this->codeWriter->findOneForUpdateByUser($user);
        if (!$code) {
            $atts = new UserAccessTemporalCodeAttributes();
            $atts->uid(Random::comb());
            $atts->user($user);
            $code = $this->codeWriter->create(UserAccessTemporalCode::create($atts));
        }
        return $code;
    }

    /**
     * Returns the most recent active TenantTermsOfUse records for the given tenant that belong
     * to any of the specified relying party codes.
     *
     * return TenantTermsOfUse[]
     */
    public function loadTenantTerms(Tenant $tenant, array $relyingParties): array
    {
        $last = [];
        $now = new DateTimeImmutable();
        $partiesIds = [];
        $pfilter = new RelyingPartyFilter();
        $allParties = $this->parties->list($pfilter);
        foreach ($allParties as $party) {
            if ($party === null) {
                continue;
            }
            if (in_array($party->getCode(), $relyingParties)) {
                $partiesIds[] = $party->uid();
            }
        }
        $query = new TenantTermsOfUseFilter(tenant: $tenant);
        $all = $this->terms->list($query);
        foreach ($all as $term) {
            if ($term === null) {
                continue;
            }
            $party = $term->getRelyingParty();
            $partyId = $party?->uid();
            if ($partyId !== null && !in_array($partyId, $partiesIds)) {
                continue;
            }
            $key = $partyId ?? '';
            $on = $term->getActivationDate();
            if (!$on || !$term->isEnabled() || $on > $now) {
                continue;
            }
            if (isset($last[$key]) && $last[$key]->getActivationDate() > $on) {
                continue;
            }
            $last[$key] = $term;
        }
        return array_values($last);
    }

    /**
     * Persists an update to the given UserAccessTemporalCode record and returns the
     * updated entity.
     */
    public function updateCode(UserAccessTemporalCode $user): UserAccessTemporalCode
    {
        return $this->codeWriter->update($user, $user);
    }

    /**
     * Looks up the tenant by name, verifying it exists and is enabled.
     * Throws LoginException with an unknowUser result if either condition is not met.
     */
    public function checkTenant(string $tenant, string $username): Tenant
    {
        $result = $this->tenants->findOneByName($tenant);
        if (!$result) {
            $this->inexistentTenant($tenant);
            throw new LoginException(auth: AuthenticationResult::unknowUser($tenant, $username));
        }
        if (!$result->isEnabled()) {
            $this->disabledTenant($tenant);
            throw new LoginException(auth: AuthenticationResult::unknowUser($tenant, $username));
        }
        return $result;
    }

    /**
     * Looks up and validates a user by their password recovery code within the given tenant.
     * Returns an array of [User, UserAccessTemporalCode] on success or throws LoginException.
     *
     * @return (User|UserAccessTemporalCode)[]
     *
     * @psalm-return list{User, UserAccessTemporalCode}
     */
    public function checkUserByRecoveryCode(Tenant $tenant, string $code): array
    {
        if ($recover = $this->codeWriter->findOneForUpdateByRecoveryCode($code)) {
            if ($theUser = $this->usersWriter->findOneForUpdateByUid($recover->getUser()->uid() ?? '')) {
                if ($tenant->uid() === $theUser->getTenant()->uid()) {
                    $username = $theUser->getName();
                    $this->checkLookupUser($tenant, $theUser, $username);
                    return [$theUser, $recover];
                }
            }
        }
        throw new LoginException(auth: AuthenticationResult::unknowUser($tenant->getName(), $code));
    }

    /**
     * Looks up and validates a user by their registration verification code within the given
     * tenant, additionally ensuring the user is still in the unverified approval state.
     * Returns an array of [User, UserAccessTemporalCode] on success or throws LoginException.
     *
     * @return (User|UserAccessTemporalCode)[]
     *
     * @psalm-return list{User, UserAccessTemporalCode}
     */
    public function checkUserByRegisterCode(Tenant $tenant, string $code): array
    {
        if ($recover = $this->codeWriter->findOneForUpdateByRegisterCode($code)) {
            if ($theUser = $this->usersWriter->findOneForUpdateByUid($recover->getUser()->uid() ?? '')) {
                if ($tenant->uid() === $theUser->getTenant()->uid()) {
                    $username = $theUser->getName();
                    $user = $this->users->findOneByTenantAndName($tenant, $username);
                    if ($user && $user->getApprove() !== UserApproveOptions::UNVERIFIED) {
                        throw new LoginException(auth: AuthenticationResult::unknowUser($tenant->getName(), $username));
                    }
                    return [$theUser, $recover];
                }
            }
        }
        throw new LoginException(auth: AuthenticationResult::unknowUser($tenant->getName(), $code));
    }

    /**
     * Looks up an active user by username or email within the given tenant.
     * Throws LoginException if the user is not found, disabled, blocked, or not yet approved.
     */
    public function checkUserNameOrEmail(Tenant $tenant, string $username): User
    {
        return $this->checkLookupUser($tenant, $this->users->findOneByTenantAndName($tenant, $username), $username);
    }

    /**
     * Looks up an active user by username within the given tenant.
     * Throws LoginException if the user is not found, disabled, blocked, or not yet approved.
     */
    public function checkUser(Tenant $tenant, string $username): User
    {
        return $this->checkLookupUser($tenant, $this->users->findOneByTenantAndName($tenant, $username), $username);
    }

    /**
     * Looks up an active user by their subject identifier (UID) within the given tenant.
     * Throws LoginException if the user is not found, disabled, blocked, or not yet approved.
     */
    public function checkUserSubjet(Tenant $tenant, string $username): User
    {
        return $this->checkLookupUser($tenant, $this->users->findOneByUid($username), $username);
    }

    /**
     * Looks up an active user by username or UID within the given tenant.
     * Tries name lookup first; falls back to UID lookup. Useful for flows where
     * the identifier may be either a username or a subject UID (e.g. session resume).
     * Throws LoginException if the user is not found, disabled, blocked, or not yet approved.
     */
    public function checkUserOrSubject(Tenant $tenant, string $username): User
    {
        $user = $this->users->findOneByTenantAndName($tenant, $username)
            ?? $this->users->findOneByUid($username);
        return $this->checkLookupUser($tenant, $user, $username);
    }

    private function checkLookupUser(Tenant $tenant, ?User $theUser, string $username): User
    {
        if (!$theUser) {
            $this->inexistentUser($tenant->getName(), $username);
            throw new LoginException(auth: AuthenticationResult::unknowUser($tenant->getName(), $username));
        }
        if ($theUser->getTenant()->uid() != $tenant->uid()) {
            $this->inexistentUser($tenant->getName(), $username);
            throw new LoginException(auth: AuthenticationResult::unknowUser($tenant->getName(), $username));
        }
        if (!$theUser->isEnabled()) {
            $this->disabledUser($tenant->getName(), $username);
            throw new LoginException(auth: AuthenticationResult::unknowUser($tenant->getName(), $username));
        }
        if ($blocked = $theUser->getBlockedUntil()) {
            if ($blocked > new DateTimeImmutable()) {
                $this->blockedUser($tenant->getName(), $username);
                throw new LoginException(auth: AuthenticationResult::unknowUser($tenant->getName(), $username));
            }
        }
        if (UserApproveOptions::ACCEPTED !== $theUser->getApprove()) {
            $this->unacceptedUser($tenant->getName(), $username);
            throw new LoginException(auth: AuthenticationResult::unknowUser($tenant->getName(), $username));
        }
        return $theUser;
    }

    private function disabledTenant(string $tenant): void
    {
        $this->logError('Try login on a disabled tenant', ['tenant-name' => $tenant]);
    }

    private function inexistentTenant(string $tenant): void
    {
        $this->logError('Try login on an inexistent tenant', ['tenant-name' => $tenant]);
    }

    private function inexistentUser(string $tenant, string $user): void
    {
        $this->logError('Try login on an inexistent user on a tenant', ['tenant-name' => $tenant, 'user-name' => $user]);
    }

    private function unacceptedUser(string $tenant, string $user): void
    {
        $this->logError('Try login with a disabled user on a tenant', ['tenant-name' => $tenant, 'user-name' => $user]);
    }

    private function disabledUser(string $tenant, string $user): void
    {
        $this->logError('Try login with a disabled user on a tenant', ['tenant-name' => $tenant, 'user-name' => $user]);
    }

    private function blockedUser(string $tenant, string $user): void
    {
        $this->logError('Try login with a blocked user on a tenant', ['tenant-name' => $tenant, 'user-name' => $user]);
    }
}
